INSERT INTO "CommunityQuestion" ("id", "authorId", "authorName", "title", "body", "createdAt", "updatedAt") VALUES ('seed-q-01', NULL, 'Priya M.', 'Which way do I read when the birds face different ways?', 'I took a photo of a lintel at the Petrie Museum and the top line has the birds facing left, but the column underneath has them facing right. I thought the rule was read towards the faces. Do I read the top line one way and the column the other, or am I misreading which is a column?', '2026-08-11T09:14:00Z', '2026-08-11T09:14:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-01-a1', 'seed-q-01', NULL, 'Dan R.', 'You have it right, and both can be true on one wall. Each line is read into the faces, so the top line goes right to left and the column goes down. Columns are read top to bottom whichever way the signs face; the facing only tells you where the line starts.', '2026-08-11T12:40:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-01-a2', 'seed-q-01', NULL, 'Harry (Learn Hieroglyphics)', 'Dan''s spot on. The other clue is symmetry: doorways often have the same text on both sides, mirrored, so the figures on each side face the middle. Nothing is wrong with the wall, it was carved to be read from the doorway.', '2026-08-12T08:05:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityQuestion" ("id", "authorId", "authorName", "title", "body", "createdAt", "updatedAt") VALUES ('seed-q-02', NULL, 'Tom W.', 'How do you actually say a word with no vowels?', 'The first lesson says nfr is ''good'' and that Egyptians did not write vowels. So how does anyone know it was said ''nefer''? Is that just a convention or did someone work it out?', '2026-08-14T19:30:00Z', '2026-08-14T19:30:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-02-a1', 'seed-q-02', NULL, 'Lena F.', 'It''s a convention. Egyptologists slip an ''e'' between consonants so words can be said out loud in a lecture. The real vowels are mostly lost, though Coptic (the last stage of the language) keeps some of them, which is how we know a few words better than others.', '2026-08-14T21:02:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-02-a2', 'seed-q-02', NULL, 'Tom W.', 'That makes sense, thank you. So ''Nefertiti'' is also partly a guess?', '2026-08-15T07:48:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-02-a3', 'seed-q-02', NULL, 'Lena F.', 'Partly. The consonants are certain, the vowels are the convention plus what Coptic and foreign transcriptions suggest. Nobody in Egypt would have said it quite the way we do.', '2026-08-15T10:15:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityQuestion" ("id", "authorId", "authorName", "title", "body", "createdAt", "updatedAt") VALUES ('seed-q-03', NULL, 'Sam K.', 'Did I write my daughter''s name right? (Chloe)', 'I used the translator for Chloe and it gave me the basket sign for the ''Ch'', then the lion, the quail chick, then the reed. Is the basket right for a hard ''k'' sound, and should there be anything for the ''e'' at the end?', '2026-08-19T15:22:00Z', '2026-08-19T15:22:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-03-a1', 'seed-q-03', NULL, 'Megan H.', 'Yes, Chloe starts with a k sound so the basket (k) is what you want, not the tethering rope (the ''ch'' as in church). The reed at the end is fine for the ''ee'' sound. I did the same for my son and put it inside a cartouche, it looks lovely.', '2026-08-19T17:00:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-03-a2', 'seed-q-03', NULL, 'Sam K.', 'Brilliant, that''s what I hoped. Cartouche it is.', '2026-08-20T08:30:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityQuestion" ("id", "authorId", "authorName", "title", "body", "createdAt", "updatedAt") VALUES ('seed-q-04', NULL, 'Megan H.', 'Any tips for remembering the owl, the water and the reed?', 'I keep mixing up which sound goes with which. The owl is m, the water is n and the reed is i, but under pressure in the games I guess. Does anyone have a picture or a phrase that made them stick?', '2026-08-23T11:05:00Z', '2026-08-23T11:05:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-04-a1', 'seed-q-04', NULL, 'Callum D.', 'The owl says ''mmm'' because it''s wise and thinking. Water ripples look like a row of n''s. The reed is a single stroke like the letter i without the dot. Silly, but I haven''t mixed them up since.', '2026-08-23T13:11:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-04-a2', 'seed-q-04', NULL, 'Rachel T.', 'The Fading Paint game helped me more than any phrase. Five minutes a day and it only asks about the ones I get wrong.', '2026-08-23T18:40:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-04-a3', 'seed-q-04', NULL, 'Megan H.', 'The ''mmm'' owl is going straight in my head. Thanks both.', '2026-08-24T09:25:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityQuestion" ("id", "authorId", "authorName", "title", "body", "createdAt", "updatedAt") VALUES ('seed-q-05', NULL, 'Alistair B.', 'Rosetta Stone at the British Museum: worth the queue?', 'Going to London next month with the kids. Is the Rosetta Stone actually readable from behind the crowd, and is there anything else in the Egyptian rooms that''s better for practising the alphabet?', '2026-08-27T20:10:00Z', '2026-08-27T20:10:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-05-a1', 'seed-q-05', NULL, 'Priya M.', 'Go early, it thins out after the first hour. You can''t read the hieroglyphic section from where you stand, it''s too small and worn, but there''s a replica you can touch nearby. Room 4 has big inscriptions on the statues where you can find cartouches at eye height, which the kids liked more.', '2026-08-28T07:55:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-05-a2', 'seed-q-05', NULL, 'Alistair B.', 'Replica you can touch is exactly the kind of thing I was after. Thank you.', '2026-08-28T21:30:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityQuestion" ("id", "authorId", "authorName", "title", "body", "createdAt", "updatedAt") VALUES ('seed-q-06', NULL, 'Lena F.', 'Folded cloth (s) versus door bolt (z): are they interchangeable?', 'The lesson lists both as s. In the words I''ve met the folded cloth is far more common. Was there ever a real difference between them, or is the bolt just an older spelling?', '2026-09-01T08:45:00Z', '2026-09-01T08:45:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-06-a1', 'seed-q-06', NULL, 'Harry (Learn Hieroglyphics)', 'Early on they were two sounds, roughly s and z, which is why they''re still transliterated differently. By the Middle Kingdom the difference had mostly gone and scribes used them interchangeably, with the folded cloth winning out. For reading, treat them both as s.', '2026-09-01T12:20:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-06-a2', 'seed-q-06', NULL, 'Lena F.', 'So the bolt is a bit like the ''ph'' in English, a spelling that outlived its sound. Got it.', '2026-09-01T14:02:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityQuestion" ("id", "authorId", "authorName", "title", "body", "createdAt", "updatedAt") VALUES ('seed-q-07', NULL, 'Mrs Okafor', 'Using this with my Year 5 class, has anyone printed the worksheet?', 'I''m planning a two-lesson block on Egypt and want the children to write their names. Has anyone used the teachers'' worksheet? Does it print well in black and white, and how long did the name activity take?', '2026-09-04T16:35:00Z', '2026-09-04T16:35:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-07-a1', 'seed-q-07', NULL, 'Dan R.', 'I ran it with a Year 4 class. Black and white is fine, the signs are line drawings. Names took about twenty minutes including the colouring in, and the ones with a ''th'' or ''v'' in their name need a word about sounds the Egyptians didn''t have, which was actually the best bit of the lesson.', '2026-09-04T19:50:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-07-a2', 'seed-q-07', NULL, 'Mrs Okafor', 'That''s very helpful, especially the point about sounds they didn''t have. I''ll build that in.', '2026-09-05T07:30:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityQuestion" ("id", "authorId", "authorName", "title", "body", "createdAt", "updatedAt") VALUES ('seed-q-08', NULL, 'Jordan P.', 'Glyphs show as empty boxes on my Android phone', 'On my laptop everything looks right but on my phone some of the signs in the glossary come up as little rectangles. It''s a Samsung, Chrome, fairly new. Is there a setting I''ve missed?', '2026-09-07T21:12:00Z', '2026-09-07T21:12:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-08-a1', 'seed-q-08', NULL, 'Harry (Learn Hieroglyphics)', 'That''s the phone missing a hieroglyph font. The lessons and games load their own font so they should be fine; if a page is still showing boxes, a hard refresh usually fixes it because the font was cached before it finished loading. If it''s still wrong after that, tell me which page and I''ll look.', '2026-09-08T08:10:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-08-a2', 'seed-q-08', NULL, 'Jordan P.', 'Hard refresh sorted it. Thanks.', '2026-09-08T18:44:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityQuestion" ("id", "authorId", "authorName", "title", "body", "createdAt", "updatedAt") VALUES ('seed-q-09', NULL, 'Callum D.', 'Why is nfr written with an extra f and r after the nfr sign?', 'In the word for ''good'' the first sign already means nfr, but then there''s a horned viper (f) and a mouth (r) as well. Isn''t that saying the sounds twice?', '2026-09-10T13:28:00Z', '2026-09-10T13:28:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-09-a1', 'seed-q-09', NULL, 'Lena F.', 'It is, on purpose. Signs that carry more than one sound often get one or two of those sounds written again afterwards, as a hint to the reader. Egyptologists call them phonetic complements. You don''t read them twice; they confirm which sign you''re looking at.', '2026-09-10T15:05:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityQuestion" ("id", "authorId", "authorName", "title", "body", "createdAt", "updatedAt") VALUES ('seed-q-10', NULL, 'Rachel T.', 'Finished the free lesson. Is the Outer Courtyard much harder?', 'I got through all 25 signs and can spell my name and the words from the first lesson. Before I pay, what''s the jump to the next lesson like? I''m not fast, I do fifteen minutes in the evening.', '2026-09-13T10:02:00Z', '2026-09-13T10:02:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-10-a1', 'seed-q-10', NULL, 'Tom W.', 'Not a big jump. The second lesson is more signs that stand for two or three sounds each, plus animals and plants, and you still have the alphabet under you. Fifteen minutes a night is exactly how I did it.', '2026-09-13T11:40:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-10-a2', 'seed-q-10', NULL, 'Megan H.', 'The third one (determinatives) was the one that made everything click for me. Worth getting to.', '2026-09-14T08:15:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityQuestion" ("id", "authorId", "authorName", "title", "body", "createdAt", "updatedAt") VALUES ('seed-q-11', NULL, 'Ben A.', 'What does the loop around a name actually mean?', 'I know a cartouche marks a royal name, but is the oval itself a sign with a meaning, or just a frame?', '2026-09-16T18:20:00Z', '2026-09-16T18:20:00Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommunityAnswer" ("id", "questionId", "authorId", "authorName", "body", "createdAt") VALUES ('seed-q-11-a1', 'seed-q-11', NULL, 'Priya M.', 'It''s a length of rope tied in a loop, the shen ring stretched out. Shen meant ''to encircle'', so the idea is that the king''s name is protected and rules over everything the sun goes round. A frame with a meaning, in other words.', '2026-09-16T20:05:00Z') ON CONFLICT ("id") DO NOTHING;
